import{_ as a,C as n,o,c as r,j as s,a as i,E as d,a2 as c}from"./chunks/framework.sc8Z_ZE3.js";const b=JSON.parse('{"title":"Access and sign-in","description":"","frontmatter":{},"headers":[],"relativePath":"admin/access.md","filePath":"admin/access.md"}'),l={name:"admin/access.md"};function h(g,e,p,u,m,f){const t=n("Badge");return o(),r("div",null,[e[0]||(e[0]=s("h1",{id:"access-and-sign-in",tabindex:"-1"},[i("Access and sign-in "),s("a",{class:"header-anchor",href:"#access-and-sign-in","aria-label":'Permalink to "Access and sign-in"'},"​")],-1)),d(t,{type:"built",text:"Built"}),e[1]||(e[1]=c(' Who can sign in, how, and for how long. Platform admins manage it under <strong>Admin › People &amp; sign-in</strong>: <strong>Users</strong>, <strong>Roles &amp; functions</strong>, <strong>Platform access</strong>, <strong>Groups</strong>, <strong>Sign-in</strong> and <strong>Access check</strong>.<h2 id="the-first-admin" tabindex="-1">The first admin <a class="header-anchor" href="#the-first-admin" aria-label="Permalink to &quot;The first admin&quot;">​</a></h2><p>On a new installation, the first admin is created with a one-time setup code: <code>docker compose logs api | grep &quot;setup code&quot;</code>, then open <code>/chat/setup</code> and enter the code, your name, email and a password of at least 12 characters. The code stays the same across restarts until it is used; afterwards the setup page is closed. See <a href="/docs/install/docker#steps">Docker Compose</a>.</p><h2 id="users" tabindex="-1">Users <a class="header-anchor" href="#users" aria-label="Permalink to &quot;Users&quot;">​</a></h2><p><strong>New user</strong> creates a local account (password at least 8 characters). Accounts are deactivated, never deleted, so their history stays. Roles and groups are assigned per user; <strong>Access check</strong> shows what a person may do and why.</p><p>Inviting people by email exists in the API but has no screen yet.</p><h2 id="single-sign-on" tabindex="-1">Single sign-on <a class="header-anchor" href="#single-sign-on" aria-label="Permalink to &quot;Single sign-on&quot;">​</a></h2><p><strong>Sign-in › Register OIDC provider</strong>: provider name, issuer URL, discovery URL (optional), client ID, client secret and scopes. Register this redirect URI with your provider: <code>https://&lt;your Octryx AI host&gt;/api/v1/auth/oidc/callback</code>.</p><ul><li><strong>Claim mappings</strong>: which claims hold the subject, email, username, display name and groups.</li><li><strong>New users</strong>: create them at their first sign-in, with default roles and groups.</li><li><strong>Group mappings</strong>: an external group gives local roles or local groups.</li><li><strong>Allow sign-in only through SSO</strong> turns off password sign-in for the web and the API. The card warns when no SSO provider is active.</li></ul><p>OpenID Connect only; SAML is not supported.</p><h2 id="how-long-a-sign-in-lasts" tabindex="-1">How long a sign-in lasts <a class="header-anchor" href="#how-long-a-sign-in-lasts" aria-label="Permalink to &quot;How long a sign-in lasts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What</th><th>Valid for</th></tr></thead><tbody><tr><td>Web sign-in</td><td>24 hours, renewed for up to 30 days</td></tr><tr><td>A pending approval</td><td>72 hours</td></tr><tr><td>A Mac or phone login</td><td>90 days by default, 1 hour to 365 days; set under <strong>Admin › Platform › Devices</strong></td></tr></tbody></table><p>Shortening the device login applies at once. Platform admins see every device under <strong>Admin › Platform › Devices</strong> and can revoke one, with a reason.</p><h2 id="linked-accounts" tabindex="-1">Linked accounts <a class="header-anchor" href="#linked-accounts" aria-label="Permalink to &quot;Linked accounts&quot;">​</a></h2><p>Each person links their accounts in other systems under <strong>My settings › Profile › Linked accounts</strong>: Atlassian Cloud, Jira or Bitbucket Server, GitHub and GitLab. A Workspace&#39;s connection verifies the account. Linked accounts let the <a href="/docs/review-bot/commands#who-may-use-them">review bot</a> know who comments, and let <strong>My work</strong> show your tickets.</p>',29))])}const y=a(l,[["render",h]]);export{b as __pageData,y as default};
